import{_ as n,o as a,c as r,a5 as i}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Sprint Plan V2 — Tổng quan định hướng (Sprint 8–12)","description":"","frontmatter":{},"headers":[],"relativePath":"plan/sprint-plan-v2-overview.md","filePath":"plan/sprint-plan-v2-overview.md"}'),e={name:"plan/sprint-plan-v2-overview.md"};function d(o,t,h,c,s,l){return a(),r("div",null,[...t[0]||(t[0]=[i(`<h1 id="sprint-plan-v2-—-tong-quan-đinh-huong-sprint-8–12" tabindex="-1">Sprint Plan V2 — Tổng quan định hướng (Sprint 8–12) <a class="header-anchor" href="#sprint-plan-v2-—-tong-quan-đinh-huong-sprint-8–12" aria-label="Permalink to &quot;Sprint Plan V2 — Tổng quan định hướng (Sprint 8–12)&quot;">​</a></h1><blockquote><p>Bản tóm tắt dễ đọc. Chi tiết task ID, Goal/AC đầy đủ nằm trong <code>brandhub-master-plan.md</code> (Phần 1.5, 1.6, Phần 2). File này chỉ để nắm hướng đi nhanh.</p><p>Chưa đẩy Jira — chờ Trung duyệt.</p></blockquote><h2 id="buc-tranh-lon" tabindex="-1">Bức tranh lớn <a class="header-anchor" href="#buc-tranh-lon" aria-label="Permalink to &quot;Bức tranh lớn&quot;">​</a></h2><p>5 sprint (10 tuần), 5 người (Trung, Lộc, Phước, Tuấn, Ân), 4 domain nghiệp vụ mới hoàn toàn (Media Package/Campaign, Task &amp; Content Workflow, Publishing &amp; Social OAuth, Analytics/Notification/Admin) + phần nền tảng cần sửa (Agency, RBAC, Billing).</p><p>Sprint 13–14 Trung tự lo (chuẩn bị bảo vệ) — không nằm trong 5 sprint này.</p><h2 id="con-đuong-khoa-chan-phai-xong-đung-thu-tu" tabindex="-1">Con đường khoá chặn (phải xong đúng thứ tự) <a class="header-anchor" href="#con-đuong-khoa-chan-phai-xong-đung-thu-tu" aria-label="Permalink to &quot;Con đường khoá chặn (phải xong đúng thứ tự)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Trung: E13 RBAC refactor → E14 permission → E16 Agency</span></span>
<span class="line"><span>                                                 │</span></span>
<span class="line"><span>                    ┌────────────────────────────┼──────────────────────┐</span></span>
<span class="line"><span>                    ▼                             ▼                      ▼</span></span>
<span class="line"><span>        Lộc: E50 Media Package/Campaign     Tuấn: E17 Billing      (không ai khác chờ)</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>                    ▼ (E50-07: approve Campaign → sinh Task)</span></span>
<span class="line"><span>        Lộc/Phước/Tuấn/Trung: E51 Task &amp; Content Workflow</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>                    ▼ (cần data thật từ E50/E51)</span></span>
<span class="line"><span>        Ân/Tuấn: E53 Analytics/Notification/Admin</span></span></code></pre></div><p><strong>Phước (E52 Publishing OAuth) và một phần Tuấn/Ân (E51 Material/Hashtag, E53 Notification/User-mgmt) hoàn toàn độc lập với chuỗi trên</strong> — chạy song song từ Sprint 8, không ai phải ngồi chờ Trung.</p><h2 id="lich-theo-sprint-tong-quan" tabindex="-1">Lịch theo sprint (tổng quan) <a class="header-anchor" href="#lich-theo-sprint-tong-quan" aria-label="Permalink to &quot;Lịch theo sprint (tổng quan)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sprint</th><th>Trọng tâm</th><th>Ai bận nhất</th><th>Ai còn nhẹ</th></tr></thead><tbody><tr><td><strong>8</strong> (08/09–22/09)</td><td>Trung dựng nền Agency/RBAC (task chặn cả dự án). Các nhánh độc lập chạy full: Phước làm OAuth Facebook/TikTok/Threads, Tuấn làm Material Repository, Ân làm Notification</td><td>Trung, Phước</td><td>—</td></tr><tr><td><strong>9</strong> (14/09–28/09)</td><td>Trung hoàn tất Agency → mở khoá Lộc (Media Package) và Tuấn (Billing) chạy full tốc</td><td>Trung, Lộc</td><td>Ân (chờ data để làm Analytics)</td></tr><tr><td><strong>10</strong> (đầu tháng 10)</td><td>Lộc vào phần khó nhất của Media Package (đàm phán 2 bên approve). Trung xong hết phần nền, chuyển sang phụ E51 (Mail Template). Phước bắt đầu các view Task (List/Calendar/Kanban)</td><td>Lộc</td><td>Ân (vẫn chờ)</td></tr><tr><td><strong>11</strong> (giữa/cuối tháng 10)</td><td>Lộc chốt Media Package → sinh Task backlog → mở khoá Approval Sequence. Ân bắt đầu code Analytics thật (đã có data). Tuấn làm Compliance/Copyright check. Trung viết QA/integration test cho E13/E14/E16 đã code Sprint 8-9 (task thật, có checklist AC — không phải &quot;hỗ trợ&quot; chung)</td><td>Lộc, Ân</td><td>— (không ai rảnh, Trung có việc QA cụ thể)</td></tr><tr><td><strong>12</strong> (đầu/giữa tháng 11)</td><td>Phước làm Approval Sequence — <strong>task rủi ro kỹ thuật cao nhất toàn dự án</strong>, không giao thêm việc khác cho Phước sprint này. Ân hoàn thiện Admin, thay hết mock service bằng API thật. Trung QA tiếp E50/E17. Tuấn QA lại toàn bộ phần E51 mình đã code (Material/Hashtag/Compliance/Copyright)</td><td>Phước</td><td>— (Trung/Tuấn có task QA cụ thể, không rảnh)</td></tr></tbody></table><h2 id="ai-lam-gi-tung-sprint-chi-tiet-theo-nguoi" tabindex="-1">Ai làm gì, từng sprint (chi tiết theo người) <a class="header-anchor" href="#ai-lam-gi-tung-sprint-chi-tiet-theo-nguoi" aria-label="Permalink to &quot;Ai làm gì, từng sprint (chi tiết theo người)&quot;">​</a></h2><p>Task ID đầy đủ (Goal/AC/Technical Notes) xem trong <code>brandhub-master-plan.md</code> Phần 2 — mục dưới chỉ nêu task ID và nội dung ngắn theo thứ tự làm.</p><h3 id="trung" tabindex="-1">Trung <a class="header-anchor" href="#trung" aria-label="Permalink to &quot;Trung&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Sprint</th><th>Task</th><th>Nội dung</th></tr></thead><tbody><tr><td>8</td><td>DA-E13-05 → E13-06 → E14-05 → E14-06 → E16-05 → E16-06</td><td>Refactor role RBAC, mở Agency Entity (task chặn cả dự án) + tạo Agency</td></tr><tr><td>9</td><td>DA-E16-07 → 08 → 09 → 10 → 12 → 11</td><td>Hoàn tất Agency: profile, xoá mềm, member, FK Workspace, template</td></tr><tr><td>10</td><td>DA-E51-06e → E51-10 → 10b → 10c → 10d → 10e</td><td>Watermark (FR 3.6.15) + toàn bộ Mail Template CRUD/Send</td></tr><tr><td>11</td><td>QA-E13 → QA-E14 → QA-E16</td><td>Viết integration test, verify từng AC cho E13/E14/E16 đã code Sprint 8-9</td></tr><tr><td>12</td><td>QA-E50 → QA-E17</td><td>Viết integration test, verify AC cho E50 (Lộc) và E17 (Tuấn)</td></tr></tbody></table><h3 id="loc" tabindex="-1">Lộc <a class="header-anchor" href="#loc" aria-label="Permalink to &quot;Lộc&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Sprint</th><th>Task</th><th>Nội dung</th></tr></thead><tbody><tr><td>8</td><td>DA-E51-01 → E51-02 → E50-01 (nếu kịp)</td><td>Collection <code>tasks</code>/<code>task_approvals</code> + bắt đầu Entity MediaPackage</td></tr><tr><td>9</td><td>DA-E50-01 (nếu chưa xong) → 02 → 03 → 08</td><td>Media Package selection flow + WorkspaceMediaPackage + ThirdPartyCollaborator</td></tr><tr><td>10</td><td>DA-E50-04 → 05 → 06 → 09</td><td>Negotiation loop 2-bên-approve (Complex nhất E50) + MediaCampaign + CampaignCollaborator</td></tr><tr><td>11</td><td>DA-E50-07 → E50-10 → E51-04</td><td>Approve Campaign → sinh Task backlog + Content Request + Task Assign</td></tr><tr><td>12</td><td>DA-E51-02/03 phối hợp Phước</td><td>Hỗ trợ kỹ thuật trực tiếp cho Approval Sequence (đã làm nền từ Sprint 8)</td></tr></tbody></table><h3 id="phuoc" tabindex="-1">Phước <a class="header-anchor" href="#phuoc" aria-label="Permalink to &quot;Phước&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Sprint</th><th>Task</th><th>Nội dung</th></tr></thead><tbody><tr><td>8</td><td>DA-E52-01 → 02 → 03 → 04</td><td>Meta OAuth (Facebook/Instagram) + TikTok/Threads OAuth</td></tr><tr><td>9</td><td>DA-E52-05 → 06 → 07 → 08</td><td>Token refresh job + callback webhook + retry backoff — xong hết E52</td></tr><tr><td>10</td><td>DA-E51-05</td><td>Task views: List/Calendar/Gantt/Kanban/Filter</td></tr><tr><td>11</td><td>DA-E51-08 → 08b → 08c → 08d → 09 → 09b</td><td>Livestream idea/script/status/meeting-link + Survey creation/analysis</td></tr><tr><td>12</td><td>DA-E51-03 → E51-14</td><td><strong>Approval Sequence state machine (rủi ro cao nhất dự án)</strong> + <code>posts</code> collection</td></tr></tbody></table><h3 id="tuan" tabindex="-1">Tuấn <a class="header-anchor" href="#tuan" aria-label="Permalink to &quot;Tuấn&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Sprint</th><th>Task</th><th>Nội dung</th></tr></thead><tbody><tr><td>8</td><td>DA-E51-06 → 06b → 06c → 06d → 06f → 06g → E53-06</td><td>Material Repository (view/add/update/remove/download) + Brand Collection + System Health</td></tr><tr><td>9</td><td>DA-E17-05 → 06 → E51-07 → 07b → 07c → 07d → 07e</td><td>UserSubscription/Transaction rename + Hashtag Collection full CRUD</td></tr><tr><td>10</td><td>DA-E17-07 → E51-13</td><td>AI Credit Ledger + Content History no-double-charge</td></tr><tr><td>11</td><td>DA-E51-11 → 12</td><td>Compliance check + Copyright infringement check</td></tr><tr><td>12</td><td>QA-E51-Tuấn</td><td>Test lại toàn bộ Material/Hashtag/Compliance/Copyright mình đã code</td></tr></tbody></table><h3 id="an" tabindex="-1">Ân <a class="header-anchor" href="#an" aria-label="Permalink to &quot;Ân&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Sprint</th><th>Task</th><th>Nội dung</th></tr></thead><tbody><tr><td>8</td><td>DA-E53-04 → 05 → 08 → 09</td><td>Notification CRUD + trigger event + User view/create/update + verify/disable</td></tr><tr><td>9</td><td>E53-04/05 dở (nếu còn) → research aggregation</td><td>Chờ E50/E51 có data — dùng thời gian chuẩn bị khung E53-01</td></tr><tr><td>10</td><td>E53-08/09 dở (nếu còn) → viết khung E53-01</td><td>Vẫn chờ data thật — research trước, code sau</td></tr><tr><td>11</td><td>DA-E53-01 → 02 → 03</td><td>Analytics aggregation API + report PDF + thay mock service (data đã có từ E50/E51)</td></tr><tr><td>12</td><td>DA-E53-07 → E53-10</td><td>Content Moderation Queue + thay toàn bộ mock service Admin bằng API thật (task đóng epic E53)</td></tr></tbody></table><h2 id="điem-rui-ro-can-đe-mat" tabindex="-1">Điểm rủi ro cần để mắt <a class="header-anchor" href="#điem-rui-ro-can-đe-mat" aria-label="Permalink to &quot;Điểm rủi ro cần để mắt&quot;">​</a></h2><ol><li><strong>DA-E16-05 (Agency Entity, Trung, Sprint 8)</strong> — chặn gần như mọi domain khác. Trễ task này = trễ dây chuyền cả Lộc và Tuấn.</li><li><strong>DA-E50-04/05 (Negotiation loop 2-bên-approve, Lộc, Sprint 10)</strong> — phức tạp nhất của Media Package, có rule ACID khó (sửa terms phải reset approval).</li><li><strong>DA-E51-03 (Approval Sequence, Phước, Sprint 12)</strong> — rủi ro cao nhất toàn dự án: reject ở bước nào phải giữ nguyên approval các bước trước, không xoá.</li><li><strong>Ân nhẹ tay ở Sprint 9–10</strong> — không phải rảnh vô ích, mà đang chờ Lộc/Trung tạo ra data thật để Analytics có gì mà tổng hợp. Nếu Sprint 8–9 Trung/Lộc trễ, Ân trễ theo dây chuyền.</li></ol><h2 id="epic-nao-keo-dai-may-sprint" tabindex="-1">Epic nào kéo dài mấy sprint <a class="header-anchor" href="#epic-nao-keo-dai-may-sprint" aria-label="Permalink to &quot;Epic nào kéo dài mấy sprint&quot;">​</a></h2><ul><li><strong>E16 (Agency)</strong> — Trung, Sprint 8–9 (2 sprint)</li><li><strong>E50 (Media Package/Campaign)</strong> — Lộc, Sprint 8–11 (4 sprint, xuyên suốt)</li><li><strong>E51 (Task &amp; Content Workflow)</strong> — Lộc/Phước/Tuấn/Trung cùng góp, Sprint 8–12 (toàn bộ 5 sprint, domain lớn nhất)</li><li><strong>E52 (Publishing OAuth)</strong> — Phước, Sprint 8–9 (xong sớm, gọn)</li><li><strong>E53 (Analytics/Notification/Admin)</strong> — Ân/Tuấn, Sprint 8–12 (kéo hết vì phải chờ data)</li><li><strong>E17 (Billing)</strong> — Tuấn, Sprint 9–10 (ngắn)</li></ul>`,26)])])}const u=n(e,[["render",d]]);export{g as __pageData,u as default};
